module adder_bcd (
    input  [3:0] A,
    input  [3:0] B,
    input  Cin,
    output reg [3:0] Sum,
    output reg Cout
);

reg [4:0] sum_int;

always @(*) begin
    sum_int = A + B + Cin;
    if (sum_int > 9) begin
        Sum = sum_int - 10;
        Cout = 1;
    end else begin
        Sum = sum_int;
        Cout = 0;
    end
end

endmodule
